-- VERIFICACIÓN POSTERIOR de NEX-068. SOLO LECTURA. Cada fila debe dar ok = true. La ejecuta el responsable en la VM INMEDIATAMENTE después de aplicar la migración:
--   docker exec -i nexit-db psql -U nexit_app -d nexit -v ON_ERROR_STOP=1 < verificar-NEX-068.sql
BEGIN READ ONLY;
SELECT 'tabla documento_electronico_entregas existe y está vacía al aplicar' AS control, to_regclass('public.documento_electronico_entregas') IS NOT NULL AND (SELECT count(*) FROM public.documento_electronico_entregas) = 0 AS ok
UNION ALL SELECT 'PK (empresa, documento) y FK a documento y dirección', EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'public.documento_electronico_entregas'::regclass AND contype = 'p') AND (SELECT count(*) FROM pg_constraint WHERE conrelid = 'public.documento_electronico_entregas'::regclass AND contype = 'f') = 3
UNION ALL SELECT 'tabla inmutable (disparador UPDATE/DELETE)', EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid = 'public.documento_electronico_entregas'::regclass AND tgname = 'fe_entregas_inmutable_trg' AND NOT tgisinternal)
UNION ALL SELECT 'las dos funciones existen, SECURITY DEFINER y con search_path fijo', (SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = 'public' AND p.proname IN ('fe_entrega_opciones', 'fe_documento_crear_fe_con_stock_entrega') AND p.prosecdef AND p.proconfig IS NOT NULL AND array_to_string(p.proconfig, ',') LIKE '%search_path=public, pg_temp%') = 2
UNION ALL SELECT 'el rol de la aplicación NO tiene acceso a la tabla de destinos', NOT (has_table_privilege('nexit_runtime', 'public.documento_electronico_entregas', 'SELECT') OR has_table_privilege('nexit_runtime', 'public.documento_electronico_entregas', 'INSERT') OR has_table_privilege('nexit_runtime', 'public.documento_electronico_entregas', 'UPDATE') OR has_table_privilege('nexit_runtime', 'public.documento_electronico_entregas', 'DELETE'))
UNION ALL SELECT 'el rol de la aplicación EJECUTA la lectura de destinos y la emisión con destino', has_function_privilege('nexit_runtime', 'public.fe_entrega_opciones(uuid,uuid,uuid)', 'EXECUTE') AND has_function_privilege('nexit_runtime', 'public.fe_documento_crear_fe_con_stock_entrega(uuid,uuid,uuid,uuid,text,uuid,text,text,text,numeric,jsonb,jsonb,uuid)', 'EXECUTE')
UNION ALL SELECT 'el rol de la aplicación NO ejecuta la emisión sin destino (NEX-067) ni la original', NOT has_function_privilege('nexit_runtime', 'public.fe_documento_crear_fe_con_stock(uuid,uuid,uuid,uuid,text,uuid,text,text,text,numeric,jsonb,jsonb)', 'EXECUTE') AND NOT has_function_privilege('nexit_runtime', 'public.fe_documento_crear_fe(uuid,uuid,uuid,uuid,text,uuid,text,text,text,numeric,jsonb)', 'EXECUTE')
UNION ALL SELECT 'PUBLIC no ejecuta ninguna función de NEX-068', NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace CROSS JOIN LATERAL aclexplode(coalesce(p.proacl, acldefault('f', p.proowner))) a WHERE n.nspname = 'public' AND p.proname IN ('fe_entrega_opciones', 'fe_documento_crear_fe_con_stock_entrega', 'fe_entregas_inmutable') AND a.grantee = 0)
UNION ALL SELECT 'NEX-067 intacta: la emisión con stock sigue existiendo (la usa el envoltorio)', to_regprocedure('public.fe_documento_crear_fe_con_stock(uuid,uuid,uuid,uuid,text,uuid,text,text,text,numeric,jsonb,jsonb)') IS NOT NULL;
ROLLBACK;
